{"command":"$root = (Resolve-Path -LiteralPath '.').Path
$main = Join-Path $root 'Asset\Blueprint\Prefabs\Monsters\MainScene'
$templateLittle = Join-Path $main 'BigLevel_01\LittleLevel_01'
$templateBig = Join-Path $main 'BigLevel_01'
if (-not (Test-Path -LiteralPath $templateLittle)) { throw "Template little level not found: $templateLittle" }
for ($i = 2; $i -le 10; $i++) {
    $name = 'LittleLevel_{0:D2}' -f $i
    $target = Join-Path $templateBig $name
    if (-not (Test-Path -LiteralPath $target)) {
        Copy-Item -LiteralPath $templateLittle -Destination $target -Recurse
    }
}
for ($b = 2; $b -le 4; $b++) {
    $name = 'BigLevel_{0:D2}' -f $b
    $target = Join-Path $main $name
    if (-not (Test-Path -LiteralPath $target)) {
        Copy-Item -LiteralPath $templateBig -Destination $target -Recurse
    }
}
Get-ChildItem -LiteralPath $main -Directory | Sort-Object Name | ForEach-Object {
    $littleCount = (Get-ChildItem -LiteralPath $_.FullName -Directory -Filter 'LittleLevel_*' | Measure-Object).Count
    [PSCustomObject]@{ BigLevel = $_.Name; LittleLevels = $littleCount }
}","workdir":"C:\WeGameApps\rail_apps\OasisEraEditor(2001776)\ShadowTrackerExtra\UGCProjects\Douluo","timeout_ms":10000}

