{"command":"$root = (Resolve-Path -LiteralPath '.').Path
$main = Join-Path $root 'Asset\Blueprint\Prefabs\Monsters\MainScene'
$source = Join-Path $main 'BigLevel_01\LittleLevel_01\BaseMons.uasset'
$sourceDir = Split-Path -Parent $source
if (-not (Test-Path -LiteralPath $source)) { throw "Source not found: $source" }
Get-ChildItem -LiteralPath $main -Directory -Filter 'BigLevel_*' | ForEach-Object {
    Get-ChildItem -LiteralPath $_.FullName -Directory -Filter 'LittleLevel_*'
} | ForEach-Object {
    $dir = $_.FullName
    if ($dir -ne $sourceDir) {
        Get-ChildItem -LiteralPath $dir -File -Filter '*.uasset' | Remove-Item -LiteralPath { $_.FullName } -Force
        Copy-Item -LiteralPath $source -Destination (Join-Path $dir 'BaseMons.uasset') -Force
    }
}
Get-ChildItem -LiteralPath $main -Directory -Filter 'BigLevel_*' | Sort-Object Name | ForEach-Object {
    Get-ChildItem -LiteralPath $_.FullName -Directory -Filter 'LittleLevel_*' | Sort-Object Name | ForEach-Object {
        $assets = Get-ChildItem -LiteralPath $_.FullName -File -Filter '*.uasset'
        [PSCustomObject]@{ BigLevel = Split-Path $_.Parent.FullName -Leaf; LittleLevel = $_.Name; UAssetCount = $assets.Count; UAsset = ($assets.Name -join ', ') }
    }
}","workdir":"C:\WeGameApps\rail_apps\OasisEraEditor(2001776)\ShadowTrackerExtra\UGCProjects\Douluo","timeout_ms":10000}
